  transform: scaleX(1);
}

@media (max-width: 640px) {
  .nav-link::after {
    bottom: -4px;
  }
}

.site-footer {
  border-top: 1px solid var(--line);
  background: color-mix(in oklab, var(--header-bg) 84%, transparent 16%);
}

.rise-in {
  animation: rise-in 700ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise-in {
