+  padding: clamp(1.75rem, 5vw, 4rem);
+  overflow: hidden;
+  border: 1px solid var(--line);
+  background:
+    linear-gradient(135deg, color-mix(in oklab, var(--surface-strong) 90%, var(--lagoon) 10%), var(--surface)),
+    var(--surface);
+  box-shadow: 0 18px 48px color-mix(in oklab, var(--sea-ink) 10%, transparent);
+}
+
+.article-hero::after {
+  position: absolute;
+  inset: 0;
+  content: "";
+  pointer-events: none;
+  opacity: 0.35;
+  background-image:
+    linear-gradient(var(--line) 1px, transparent 1px),
+    linear-gradient(90deg, var(--line) 1px, transparent 1px);
+  background-size: 2rem 2rem;
+  mask-image: linear-gradient(90deg, transparent, black 70%);
+}
+
+.article-hero > * {
+  position: relative;
+  z-index: 1;
+}
+
+.article-meta,
+.section-label {
+  margin: 0;
+  color: var(--kicker);
+  font-size: 0.72rem;
+  font-weight: 800;
+  letter-spacing: 0.13em;
+  text-transform: uppercase;
+}
+
+.article-meta {
+  display: flex;
+  gap: 0.6rem;
+  align-items: center;
+}
+
+.article-hero h1,
+.article-section h2,
+.premise-callout h2,
+.article-sources h2 {
+  font-family: "Fraunces", Georgia, serif;
+  color: var(--sea-ink);
+}
+
+.article-hero h1 {
+  max-width: 11ch;
+  margin: 1rem 0 1.25rem;
+  font-size: clamp(3rem, 8vw, 5.8rem);
+  line-height: 0.94;
+  letter-spacing: -0.055em;
+}
+
+.article-dek {
+  max-width: 55ch;
+  margin: 0;
+  color: var(--sea-ink-soft);
+  font-size: clamp(1rem, 2vw, 1.2rem);
+  line-height: 1.75;
+}
+
+.article-byline {
+  margin: 1.75rem 0 0;
+  color: var(--sea-ink-soft);
+  font-size: 0.82rem;
+  font-weight: 700;
+}
+
+.premise-callout {
+  margin: clamp(2rem, 5vw, 4rem) 0;
+  padding: clamp(1.5rem, 4vw, 2.4rem);
+  border-left: 4px solid var(--article-warning-line);
+  background: var(--article-warning-bg);
+  color: var(--article-warning);
+}
+
+.premise-callout .section-label,
+.premise-callout h2 {
+  color: var(--article-warning);
+}
+
+.premise-callout h2 {
+  margin: 0.65rem 0;
+  font-size: clamp(1.7rem, 4vw, 2.4rem);
+  line-height: 1.08;
+}
+
+.premise-callout p:last-child {
+  max-width: 62ch;
+  margin: 0;
+  line-height: 1.7;
+}
+
+.article-section {
+  margin-top: clamp(3.5rem, 8vw, 6.5rem);
+  scroll-margin-top: 6rem;
+}
+
+.article-section h2,
+.article-sources h2 {
+  margin: 0.7rem 0 1.35rem;
+  font-size: clamp(2rem, 5vw, 3.25rem);
+  line-height: 1;
+  letter-spacing: -0.035em;
+}
+
+.article-section p {
+  margin: 1.25rem 0;
+  color: var(--sea-ink-soft);
+  font-size: 1rem;
+  line-height: 1.85;
+}
+
+.article-section a,
+.article-sources a {
+  color: var(--lagoon-deep);
+  font-weight: 700;
+}
+
+.attack-chain {
+  margin: 2.25rem 0;
+  padding: clamp(1.25rem, 4vw, 2rem);
+  border: 1px solid var(--line);
+  background: var(--surface);
+}
+
+.attack-chain figcaption {
+  color: var(--sea-ink);
+  font-size: 0.85rem;
+  font-weight: 800;
+}
+
+.attack-chain ol,
+.checklist {
+  padding: 0;
+  list-style: none;
+}
+
+.attack-chain ol {
+  display: grid;
+  gap: 1rem;
+  margin: 1.3rem 0 0;
+}
+
+.attack-chain li {
+  display: grid;
+  grid-template-columns: 2.4rem 1fr;
+  gap: 0.85rem;
+  padding-top: 1rem;
+  border-top: 1px solid var(--line);
+}
+
+.attack-chain li > span {
+  color: var(--lagoon-deep);
+  font-size: 0.75rem;
+  font-weight: 800;
+  letter-spacing: 0.08em;
+}
+
+.attack-chain strong {
+  color: var(--sea-ink);
+  font-size: 0.95rem;
+}
+
+.attack-chain p {
+  margin: 0.25rem 0 0;
+  font-size: 0.88rem;
+  line-height: 1.65;
+}
+
+.terminal-code {
+  max-width: 100%;
+  margin: 1.75rem 0;
+  padding: 1.25rem;
+  overflow-x: auto;
+  border: 1px solid color-mix(in oklab, var(--lagoon) 36%, transparent);
+  background: var(--article-terminal);
+  box-shadow: inset 0 1px 0 color-mix(in oklab, var(--article-terminal-text) 14%, transparent);
+  color: var(--article-terminal-text);
+  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
+  font-size: 0.8rem;
+  line-height: 1.7;
+}
+
+.terminal-code code {
+  white-space: pre;
+}
+
+.control-grid {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 1px;
+  overflow: hidden;
+  border: 1px solid var(--line);
+  background: var(--line);
+}
+
+.control-grid > div {
+  padding: 1.3rem;
+  background: var(--surface);
+}
+
+.control-grid h3 {
+  margin: 0;
+  color: var(--sea-ink);
+  font-size: 0.93rem;
+}
+
+.control-grid p {
+  margin: 0.7rem 0 0;
+  font-size: 0.88rem;
+  line-height: 1.7;
+}
+
+.incident-note {
+  padding: 1rem 1.15rem;
+  border: 1px solid var(--article-warning-line);
+  background: var(--article-warning-bg);
+  color: var(--article-warning) !important;
+}
+
+.incident-note strong {
+  color: inherit;
+}
+
+.checklist {
+  display: grid;
+  gap: 0.75rem;
+  counter-reset: checklist;
+}
+
+.checklist li {
+  display: grid;
+  grid-template-columns: 2.2rem 1fr;
+  gap: 0.8rem;
+  align-items: center;
+  padding: 0.95rem 0;
+  border-bottom: 1px solid var(--line);
+  color: var(--sea-ink);
+  font-weight: 700;
+  line-height: 1.45;
+  counter-increment: checklist;
+}
+
+.checklist li::before {
+  content: "0" counter(checklist);
+  color: var(--lagoon-deep);
+  font-size: 0.75rem;
+  font-weight: 800;
+  letter-spacing: 0.08em;
+}
+
+.article-sources {
+  margin-top: clamp(4rem, 9vw, 7rem);
+  padding: clamp(1.5rem, 4vw, 2.5rem);
+  border: 1px solid var(--line);
+  background: color-mix(in oklab, var(--surface-strong) 86%, var(--lagoon) 14%);
+}
+
+.article-sources ul {
+  display: grid;
+  gap: 0.8rem;
+  padding: 0;
+  margin: 0;
+  list-style: none;
+}
+
+.article-sources li {
+  padding-bottom: 0.8rem;
+  border-bottom: 1px solid var(--line);
+  color: var(--sea-ink-soft);
+  font-size: 0.9rem;
+  line-height: 1.5;
+}
+
+.article-sources li:last-child {
+  padding-bottom: 0;
+  border-bottom: 0;
+}
+
+.article-sources span {
+  color: var(--sea-ink-soft);
+  font-size: 0.8rem;
+}
+
+.publication-footer {
+  border-top: 1px solid var(--line);
+  background: color-mix(in oklab, var(--header-bg) 88%, transparent);
+}
+
+.publication-footer-inner {
+  display: flex;
+  justify-content: space-between;
+  gap: 1rem;
+  padding-block: 1.75rem;
+}
+
+.publication-footer p {
+  margin: 0;
+  color: var(--sea-ink-soft);
+  font-size: 0.78rem;
+}
+
+@media (max-width: 640px) {
+  .publication-nav {
+    min-height: 0;
+    flex-wrap: wrap;
+    gap: 0.75rem;
+    padding-block: 0.8rem;
+  }
+
+  .article-nav {
+    order: 3;
+    width: 100%;
+    justify-content: space-between;
+    gap: 0.5rem;
+  }
+
+  .article-nav a {
+    font-size: 0.7rem;
+  }
+
+  .article-page {
+    padding-inline: 0.75rem;
+  }
+
+  .article-hero {
+    padding: 1.5rem;
+  }
+
+  .control-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .publication-footer-inner {
+    flex-direction: column;
+  }
+}
