    --article-warning: #ffe0a4;
    --article-warning-bg: #33270e;
    --article-warning-line: #d69b2d;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#app {
  min-height: 100%;
}

body {
  margin: 0;
  color: var(--sea-ink);
  font-family: var(--font-sans);
  background-color: var(--bg-base);
  background:
    radial-gradient(1100px 620px at -8% -10%, var(--hero-a), transparent 58%),
    radial-gradient(1050px 620px at 112% -12%, var(--hero-b), transparent 62%),
    radial-gradient(720px 380px at 50% 115%, rgba(79, 184, 178, 0.1), transparent 68%),
    linear-gradient(180deg, color-mix(in oklab, var(--sand) 68%, white) 0%, var(--foam) 44%, var(--bg-base) 100%);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  opacity: 0.28;
  background:
    radial-gradient(circle at 20% 15%, rgba(255, 255, 255, 0.8), transparent 34%),
    radial-gradient(circle at 78% 26%, rgba(79, 184, 178, 0.2), transparent 42%),
    radial-gradient(circle at 42% 82%, rgba(47, 106, 74, 0.14), transparent 36%);
}

body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  opacity: 0.14;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 28px 28px;
  mask-image: radial-gradient(circle at 50% 30%, black, transparent 78%);
}

a {
  color: var(--lagoon-deep);
  text-decoration-color: rgba(50, 143, 151, 0.4);
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}

a:hover {
  color: #246f76;
}

code {
  font-size: 0.9em;
  border: 1px solid var(--line);
  background: color-mix(in oklab, var(--surface-strong) 82%, white 18%);
  border-radius: 7px;
  padding: 2px 7px;
}

pre code {
  border: 0;
  background: transparent;
  padding: 0;
  border-radius: 0;
  font-size: inherit;
  color: inherit;
}

.page-wrap {
  width: min(1180px, calc(100% - 2rem));
  margin-inline: auto;
}

button,
a {
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease,
    transform 180ms ease;
}

.publication-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid var(--line);
  background: var(--header-bg);
  backdrop-filter: blur(16px);
}

.publication-nav {
  display: flex;
  min-height: 4.5rem;
  align-items: center;
  gap: 1.5rem;
}

.publication-mark {
  color: var(--sea-ink);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-decoration: none;
  white-space: nowrap;
}

.article-nav {
  display: flex;
  gap: 1.25rem;
  margin-left: auto;
}

.article-nav a,
.publication-footer a {
  color: var(--sea-ink-soft);
  font-size: 0.78rem;
  font-weight: 700;
  text-decoration: none;
}

.article-nav a:hover,
.publication-footer a:hover {
  color: var(--lagoon-deep);
}

.article-page {
  padding: clamp(2.5rem, 7vw, 6.5rem) 1rem clamp(4rem, 8vw, 7rem);
}

.security-article {
  width: min(760px, 100%);
  margin-inline: auto;
}

.article-hero {
  position: relative;
  padding: clamp(1.75rem, 5vw, 4rem);
  overflow: hidden;
  border: 1px solid var(--line);
  background:
    linear-gradient(135deg, color-mix(in oklab, var(--surface-strong) 90%, var(--lagoon) 10%), var(--surface)),
    var(--surface);
  box-shadow: 0 18px 48px color-mix(in oklab, var(--sea-ink) 10%, transparent);
}

.article-hero::after {
  position: absolute;
  inset: 0;
  content: "";
  pointer-events: none;
  opacity: 0.35;
  background-image:
    linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size: 2rem 2rem;
  mask-image: linear-gradient(90deg, transparent, black 70%);
}

.article-hero > * {
  position: relative;
  z-index: 1;
}

.article-meta,
.section-label {
  margin: 0;
  color: var(--kicker);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.article-meta {
  display: flex;
  gap: 0.6rem;
  align-items: center;
}

.article-hero h1,
.article-section h2,
.premise-callout h2,
.article-sources h2 {
  font-family: "Fraunces", Georgia, serif;
  color: var(--sea-ink);
}

.article-hero h1 {
  max-width: 11ch;
  margin: 1rem 0 1.25rem;
  font-size: clamp(3rem, 8vw, 5.8rem);
  line-height: 0.94;
  letter-spacing: -0.055em;
}

.article-dek {
  max-width: 55ch;
