  background: var(--article-warning-bg);
  color: var(--article-warning);
}

.premise-callout .section-label,
.premise-callout h2 {
  color: var(--article-warning);
}

.premise-callout h2 {
  margin: 0.65rem 0;
  font-size: clamp(1.7rem, 4vw, 2.4rem);
  line-height: 1.08;
}

.premise-callout p:last-child {
  max-width: 62ch;
  margin: 0;
  line-height: 1.7;
}

.article-section {
  margin-top: clamp(3.5rem, 8vw, 6.5rem);
  scroll-margin-top: 6rem;
}

.article-section h2,
.article-sources h2 {
  margin: 0.7rem 0 1.35rem;
  font-size: clamp(2rem, 5vw, 3.25rem);
  line-height: 1;
  letter-spacing: -0.035em;
}

.article-section p {
  margin: 1.25rem 0;
  color: var(--sea-ink-soft);
  font-size: 1rem;
  line-height: 1.85;
}

.article-section a,
.article-sources a {
  color: var(--lagoon-deep);
  font-weight: 700;
}

.attack-chain {
  margin: 2.25rem 0;
  padding: clamp(1.25rem, 4vw, 2rem);
  border: 1px solid var(--line);
  background: var(--surface);
}

.attack-chain figcaption {
  color: var(--sea-ink);
  font-size: 0.85rem;
  font-weight: 800;
}

.attack-chain ol,
.checklist {
  padding: 0;
  list-style: none;
}

.attack-chain ol {
  display: grid;
  gap: 1rem;
  margin: 1.3rem 0 0;
}

.attack-chain li {
  display: grid;
  grid-template-columns: 2.4rem 1fr;
  gap: 0.85rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line);
}

.attack-chain li > span {
