.publication-footer {
  border-top: 1px solid var(--line);
  background: color-mix(in oklab, var(--header-bg) 88%, transparent);
}

.publication-footer-inner {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 1.75rem;
}

.publication-footer p {
